typedef struct Node { int data; struct Node *next; } Node;

int delAll(Node *head, int x)
{
    int cnt = 0;
    Node *p = head, *q;
    while (p->next) {
        if (p->next->data == x) {
            q = p->next;
            p->next = q->next;   /* 先接后断 */
            free(q);
            cnt++;
        } else {
            p = p->next;
        }
    }
    return cnt;
}
```

