questions.answer:
```c
#include <stdio.h>
int main(void)
{
    char s[100];
    int i, up = 0, low = 0, dig = 0, other = 0;
    gets(s);            /* 或 fgets(s, sizeof s, stdin) */
    for (i = 0; s[i]; i++) {
        if (s[i] >= 'A' && s[i] <= 'Z') up++;
        else if (s[i] >= 'a' && s[i] <= 'z') low++;
        else if (s[i] >= '0' && s[i] <= '9') dig++;
        else other++;
    }
    printf("%d %d %d %d\n", up, low, dig, other);
    return 0;
}
```

